#!/bin/bash

###############################################################################
# Test script to show example arithmetic questions generated by uninstall-verification.sh
###############################################################################

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
LIB_DIR="${SCRIPT_DIR}/lib"

# Source the verification module
if [ -f "${LIB_DIR}/uninstall-verification.sh" ]; then
    source "${LIB_DIR}/uninstall-verification.sh"
else
    echo "Error: Could not find uninstall-verification.sh" >&2
    exit 1
fi

echo "Example Arithmetic Questions Generated by uninstall-verification.sh"
echo "===================================================================="
echo ""
echo "The function generates arithmetic questions in word form to prevent"
echo "copy-pasting into browsers. Questions use three complexity levels:"
echo "1. Medium: a * b + (c * d) or a * b - (c * d) or a * b + (c - d)"
echo "2. Complex: a * b op1 (c * d) op2 (e op3 f) op4 g"
echo ""
echo "Here are example questions:"
echo ""

# Generate multiple questions and show them.
# Note: "Simple" questions were removed from the generator by design, so this script
# only displays Medium and Complex examples.

echo "=== MEDIUM QUESTIONS (with one set of parentheses) ==="
echo ""
medium_count=0
attempts=0
max_attempts=500
while [ ${medium_count} -lt 5 ] && [ ${attempts} -lt ${max_attempts} ]; do
    attempts=$((attempts + 1))
    question_data=$(generate_algebra_question)
    question_text=$(echo "${question_data}" | cut -d'|' -f1)
    correct_answer=$(echo "${question_data}" | cut -d'|' -f2)
    
    # Check if it's medium (one set of parentheses, not two)
    paren_count=$(echo "${question_text}" | grep -o "(" | wc -l)
    if [ ${paren_count} -eq 1 ]; then
        medium_count=$((medium_count + 1))
        echo "Example ${medium_count}:"
        echo "  Question: ${question_text}"
        echo "  Correct Answer: ${correct_answer}"
        echo ""
    fi
done
if [ ${medium_count} -lt 5 ]; then
    echo "Note: Only generated ${medium_count}/5 medium questions after ${attempts} attempts."
    echo ""
fi

echo ""
echo "=== COMPLEX QUESTIONS (with multiple parentheses) ==="
echo ""
complex_count=0
attempts=0
while [ ${complex_count} -lt 5 ] && [ ${attempts} -lt ${max_attempts} ]; do
    attempts=$((attempts + 1))
    question_data=$(generate_algebra_question)
    question_text=$(echo "${question_data}" | cut -d'|' -f1)
    correct_answer=$(echo "${question_data}" | cut -d'|' -f2)
    
    # Check if it's complex (two sets of parentheses)
    paren_count=$(echo "${question_text}" | grep -o "(" | wc -l)
    if [ ${paren_count} -ge 2 ]; then
        complex_count=$((complex_count + 1))
        echo "Example ${complex_count}:"
        echo "  Question: ${question_text}"
        echo "  Correct Answer: ${correct_answer}"
        echo ""
    fi
done
if [ ${complex_count} -lt 5 ]; then
    echo "Note: Only generated ${complex_count}/5 complex questions after ${attempts} attempts."
    echo ""
fi

echo ""
echo "===================================================================="
echo "Summary:"
echo "  - All questions are written in word form (e.g., 'times', 'plus', 'minus')"
echo "  - This prevents users from easily copy-pasting into browsers or calculators"
echo "  - Questions use parentheses correctly to ensure proper order of operations"
echo "  - Answers are simple integers (may be negative)"
echo ""
echo "In actual use during uninstall verification:"
echo "  - 10 random questions (any mix of these 3 complexity levels) are generated"
echo "  - User must answer ALL 10 correctly to proceed"
echo "  - User gets up to 3 attempts per question"
echo "  - Answers are validated as integers (commas and spaces are stripped)"
